import os, re

def load():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t = open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read()
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows_raw = t[m.end():].split('\n')[:h]
        rows = [r.split() for r in rows_raw if r.strip()]
        if k not in G and all(len(rows) == len(r) and all(x.isdigit() for x in r.replace(' ', '')) for r in rows):
            G[k] = [[int(x) for x in r.split()] for r in rows]
    return G

G = load()
print(f"Keys found: {sorted(G.keys())}")
for k, v in sorted(G.items()):
    print(f"{k}: {v}")

